import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeTextField;
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeOutlinedButton, PrimeTextButton;
import '../../src/localization/live_screen_text.dart';import '../../theme/theme_center_text_generated.dart';
import 'package:primecare_ui_foundation/primecare_ui_foundation.dart' show PrimeText;
import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../theme/personal_theme.dart';import '../../theme/theme_center_catalog_generated.dart';import '../../theme/theme_library_provider.dart';import '../../theme/theme_settings_provider.dart';
String themeCenterText(BuildContext context,String key,{Map<String,String> args=const {}}) {final language=Localizations.localeOf(context).languageCode;return liveScreenText(context,'theme_center',language,key,themeCenterScreenCatalog[language]?[key]??themeCenterScreenCatalog['en']![key]!,args:args);}
class ThemeCenterPanel extends ConsumerWidget {
 const ThemeCenterPanel({super.key});
 Future<void> _run(BuildContext context,Future<void> Function() action) async {try{await action();}catch(_){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:PrimeText(themeCenterText(context,'unable_to_save_or_apply_use_a_unique_name_and_valid_settings'))));}}
 Future<String?> _name(BuildContext context,String initial) async {final controller=TextEditingController(text:initial);final result=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:PrimeText(themeCenterText(context,'theme_name')),content:PrimeTextField(controller:controller,maxLength:60,autofocus:true),actions:[PrimeTextButton(onPressed:()=>Navigator.pop(c),child:PrimeText(themeCenterText(context,'cancel'))),FilledButton(onPressed:()=>Navigator.pop(c,controller.text),child:PrimeText(themeCenterText(context,'save')))]));controller.dispose();return result;}
 Future<PersonalTheme?> _edit(BuildContext context,PersonalTheme initial) async {
  final controllers={for(final key in themeCenterColorKeys)key:TextEditingController(text:initial.colors[key]??'')};var font=initial.fontFamily,scale=initial.fontScale,radius=initial.radius;
  final result=await showDialog<PersonalTheme>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setState)=>AlertDialog(title:PrimeText(themeCenterText(context,'edit_theme')),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:font,decoration:InputDecoration(labelText:themeCenterText(context,'font')),items:['system','serif','monospace'].map((f)=>DropdownMenuItem(value:f,child:PrimeText(themeCenterText(context,'font.$f')))).toList(),onChanged:(v)=>setState(()=>font=v!)),PrimeText('${themeCenterText(context,'text_scale')}: ${scale.toStringAsFixed(3)}'),Slider(value:scale,min:.875,max:1.5,divisions:5,onChanged:(v)=>setState(()=>scale=v)),PrimeText('${themeCenterText(context,'corner_radius')}: $radius'),Slider(value:radius.toDouble(),min:0,max:24,divisions:24,onChanged:(v)=>setState(()=>radius=v.round())),...themeCenterColorKeys.map((key)=>PrimeTextField(controller:controllers[key],maxLength:7,decoration:InputDecoration(labelText:themeCenterText(context,'color.$key'),hintText:'#RRGGBB'))),PrimeText(themeCenterText(context,'leave_colors_empty_to_inherit_the_palette_text_contrast_adjusts_automa'))]))),actions:[PrimeTextButton(onPressed:()=>Navigator.pop(c),child:PrimeText(themeCenterText(context,'cancel'))),FilledButton(onPressed:(){try{final theme=PersonalTheme(name:initial.name,preset:initial.preset,fontFamily:font,fontScale:scale,radius:radius,colors:{for(final entry in controllers.entries)if(entry.value.text.trim().isNotEmpty)entry.key:entry.value.text.trim()}).validated();Navigator.pop(c,theme);}catch(_){ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:PrimeText(themeCenterText(c,'invalidColor'))));}},child:PrimeText(themeCenterText(context,'apply')))])));
  for(final c in controllers.values)c.dispose();return result;
 }
 @override Widget build(BuildContext context,WidgetRef ref) {
  final current=ref.watch(themeSettingsProvider).theme,items=ref.watch(themeLibraryProvider);final settings=ref.read(themeSettingsProvider.notifier),library=ref.read(themeLibraryProvider.notifier);
  return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[PrimeText(themeCenterText(context,'theme_center_heading'),style:Theme.of(context).textTheme.titleMedium),PrimeText(themeCenterText(context,'personal_themes_are_saved_for_this_account_and_role_on_this_device')),Wrap(spacing:8,children:[PrimeOutlinedButton(onPressed:()=>_run(context,()async{final edited=await _edit(context,current);if(edited!=null)await settings.applyPersonalTheme(edited);}),child:PrimeText(themeCenterText(context,'edit_current'))),FilledButton(onPressed:()=>_run(context,()async{final name=await _name(context,current.name);if(name!=null)await library.save(current.named(name));}),child:PrimeText(themeCenterText(context,'save_as_new'))),PrimeOutlinedButton(onPressed:()=>_run(context,()async{await Clipboard.setData(ClipboardData(text:current.exportJson()));if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:PrimeText(themeCenterText(context,'theme_json_copied'))));}),child:PrimeText(themeCenterText(context,'export'))),PrimeOutlinedButton(onPressed:()=>_run(context,()async{final controller=TextEditingController();final value=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:PrimeText(themeCenterText(context,'import_theme_json')),content:PrimeTextField(controller:controller,maxLength:16384,maxLines:8),actions:[PrimeTextButton(onPressed:()=>Navigator.pop(c),child:PrimeText(themeCenterText(context,'cancel'))),FilledButton(onPressed:()=>Navigator.pop(c,controller.text),child:PrimeText(themeCenterText(context,'import')))]));controller.dispose();if(value!=null)await settings.applyPersonalTheme(PersonalTheme.importJson(value));}),child:PrimeText(themeCenterText(context,'import')))]),...items.map((item)=>ListTile(title:PrimeText(item.theme.name),subtitle:PrimeText(item.theme.preset),onTap:()=>_run(context,()=>settings.applyPersonalTheme(item.theme)),trailing:PopupMenuButton<String>(onSelected:(action)=>_run(context,()async{if(action=='delete'){await library.remove(item.id);return;}if(action=='update'){await library.save(current.named(item.theme.name),id:item.id);return;}final name=await _name(context,action=='duplicate'?themeCenterText(context,'copyName',args:{'name':item.theme.name}):item.theme.name);if(name==null)return;if(action=='rename'){await library.rename(item.id,name);if(current.name==item.theme.name)await settings.applyPersonalTheme(current.named(name));}else await library.duplicate(item.id,name);}),itemBuilder:(c)=>[PopupMenuItem(value:'update',child:PrimeText(themeCenterText(context,'update_from_current'))),PopupMenuItem(value:'rename',child:PrimeText(themeCenterText(context,'rename'))),PopupMenuItem(value:'duplicate',child:PrimeText(themeCenterText(context,'duplicate'))),PopupMenuItem(value:'delete',child:PrimeText(themeCenterText(context,'delete')))]))),const SizedBox(height:24)]);
 }
}
